import{_ as l,l as i,o as e,c as n,v as o,p as s,x as t,d as E,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"1970 年代滞胀","description":"","frontmatter":{"title":"1970 年代滞胀","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/stagflation-1970s.md","filePath":"econ/stagflation-1970s.md","lastUpdated":1789023840000}'),p={name:"econ/stagflation-1970s.md"};function A(B,a,h,_,u,m){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="_1970-年代滞胀" tabindex="-1">1970 年代滞胀 <a class="header-anchor" href="#_1970-年代滞胀" aria-label="Permalink to &quot;1970 年代滞胀&quot;">​</a></h1><div class="epigraph"><p>供给冲击把菲利普斯曲线外移；适应性或弱锚定的预期把一次价格跳变写成持续通胀；货币政策若稳定失业而迁就，通胀就停不下来。滞胀是这三层叠在一起，不是「曲线失效」四个字。</p><footer>—— Gordon 的供给冲击与菲利普斯曲线；Lucas, Econometric Policy Evaluation: A Critique, 1976；Volcker 紧缩的经验对照；Blinder 对大通胀的叙述</footer></div><p><a href="/econ/bretton-woods-collapse">上一课</a>把定锚从黄金换成浮动后的国内政策。本课缺口是 1970 年代：高通胀与高失业并存。石油与粮食是供给冲击；工会与工资指数化是传播；美联储在 Burns 时期把失业目标放在通胀前面，是迁就。Lucas 批判警告：把 1960 年代的曲线当结构去「买」更低失业，预期一变曲线就移。后课东亚危机换到钉住与短期外债，不再堆石油年表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>需求拉动下，通胀与失业短期替代。供给冲击：\\(P\\) 升、\\(Y\\) 降，替代消失。若预期把核心通胀抬高，名义冲击过后仍要更高的通胀才能维持原失业。缺口不是再画一次曲线，而是：<strong>冲击可以是暂时的，定锚失败使它变成十年。</strong> 财政赤字与商品税不是本课主角，但赤字货币化会加强迁就。浮动汇率让各国选择不同的 \\(M\\)：西德更早稳定，美国更晚——截面又一次当证据，类似金本位脱离时点。</p><h3 id="滞胀不是菲利普斯曲线「失效」" tabindex="-1">滞胀不是菲利普斯曲线「失效」 <a class="header-anchor" href="#滞胀不是菲利普斯曲线「失效」" aria-label="Permalink to &quot;滞胀不是菲利普斯曲线「失效」&quot;">​</a></h3><p>曲线在给定预期下仍可以有短期斜率；失效的是把这条斜率当可永久开采的结构。Lucas 1976 正是对着这种政策评价。供给冲击解释「为何同时坏」；预期与政策规则解释「为何持续」。只骂曲线，会漏掉 Volcker 用衰退把预期拧回来的那一截——那是代价，也是机制证据。</p><p><span class="marginnote">Blinder 把大通胀写成政策错误加冲击，而不是神秘的制度命运。Volcker 紧缩证明：再通胀预期可以被高利率打破，代价是深度衰退。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层。(1) 供给：石油、生产率减速，AS 内移。(2) 预期：适应性或弱锚定，工资物价螺旋。(3) 规则：利率对通胀反应不足（泰勒原则的反面），失业优先。对照：金本位下是通缩枷锁；布雷顿崩溃后是通胀枷锁缺失。政策实验是 Volcker：提高 \\(i\\)，失业升，通胀随后降——与「冲击永远主导」不相容。后课央行独立性把这次实验收成制度。同一供给冲击下，名义锚更硬的经济核心通胀爬升更慢——截面再一次当证据，类似脱离金本位的时点。</p>',10)),(e(),s(d,null,{default:t(()=>[c(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FLOAT%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E9%BB%84%E9%87%91%E9%94%9A%E6%B6%88%E5%A4%B1%22%5D%20--%3E%20SHOCK%5B%22%E4%BE%9B%E7%BB%99%E5%86%B2%E5%87%BB%E5%A4%96%E7%A7%BB%20AS%22%5D%0A%20%20SHOCK%20--%3E%20EXP%5B%22%E9%A2%84%E6%9C%9F%E6%9C%AA%E9%94%9A%E5%AE%9A%22%5D%0A%20%20EXP%20--%3E%20ACC%5B%22%E8%B4%A7%E5%B8%81%E8%BF%81%E5%B0%B1%22%5D%0A%20%20ACC%20--%3E%20VOL%5B%22Volcker%3A%20%E7%94%A8%E8%A1%B0%E9%80%80%E9%87%8D%E6%96%B0%E5%AE%9A%E9%94%9A%22%5D%0A%20%20VOL%20--%3E%20ASIA%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E9%92%89%E4%BD%8F%E5%8A%A0%E5%A4%96%E5%80%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>不要用滞胀否定所有短期乘数：状态是高通胀弱锚，不是流动性陷阱。两套宏观状态，乘数课已经分开。工资指数化把相对价格冲击写成自动的第二轮；若指数化覆盖面广，一次性石油涨价会变成核心通胀，央行再迁就就进入螺旋。这是制度传播，不是石油桶数本身。锚比冲击更决定持续期，而不是桶数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是定锚缺失下的供给冲击放大。相对价格应当一次调整；工资指数化与迁就的 \\(M\\) 把相对价格变成总价格水平的持续上升。浮动使各国 \\(M\\) 可分，于是「谁更早接受失业换锚」成为截面。与金本位对照：那里政策不能再通胀；这里政策可以，却选了再通胀。约束从金属换成了政治。Lucas 批判是同一机制的计量表达：简化式含旧规则。</p><p>石油以美元计价，美元在布雷顿崩溃后贬值，冲击幅度含汇率——时序接头，不是「都是石油的错」的单一因果。财政若用扭曲税或管制价格去「遮」相对价格，短缺与黑市会把官方指数压住、把真实 \\(P\\) 推得更乱，计量上的菲利普斯更脏。本课要的是定锚，不是价格管制史。</p><p><span class="marginnote">Gordon 把菲利普斯曲线写成惯性加供给因素加需求缺口。本课用它当组织，不把某一国回归系数当普适常数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写能源交易，不把每次欧佩克会议编年。资本税与供给学派口号不是机制核心。下一课：新兴市场的钉住加原罪，失败形态从通胀螺旋换成突然停止。后课默认：滞胀用供给冲击 × 弱锚 × 迁就来读；Volcker 是重新定锚的代价证据。不要只说「曲线死了」。工资–物价管制若短暂压住指数，预期仍可在黑市与合同指数化里存活，解除管制后通胀会跳回来——那是锚没钉住的另一条证据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>供给冲击造成通胀与失业同时坏；弱锚使它持续。</li><li>菲利普斯短期斜率不是可永久开采的结构。</li><li>浮动后各国定锚分化；Volcker 用衰退拧回预期。</li><li>与金本位通缩枷锁对照：这里是通胀枷锁缺失。</li><li>指数化与迁会使一次相对价格冲击变成核心通胀螺旋。</li><li>出处：Gordon；Lucas 1976；Blinder；Volcker 时期经验。</li></ul>',9))])}const P=l(p,[["render",A]]);export{k as __pageData,P as default};
